  'Summary: ' + esc(req.summary || '')
]);
return [{ json: {
  to: s.support_email, subject: 'Ticket ' + id + ': order ' + o.order_number + ' (' + clip(req.summary || 'help chat', 60) + ')', html, kind: 'support_ticket', ref: id,
