  status: 'Shipped ' + day(o.shipped_at) + ' with ' + o.carrier + '. Last tracking update: "' + o.last_event + '" on ' + day(o.last_event_at) + '. Estimated delivery: ' + day(o.estimated_delivery) + '.',
